#ifndef CG50_REVE_TX_LEASE_H
#define CG50_REVE_TX_LEASE_H
#include <stdint.h>
#include "wire.h"
/* Physical heartbeat is generated by the main loop, never autonomous PWM. */
struct TxLease {
 bool active=false;uint32_t lastFrame=0,lastPulse=0;
 static constexpr uint32_t TIMEOUT_MS=30000,PULSE_MS=10;
 bool expired(uint32_t now)const{return active&&(uint32_t)(now-lastFrame)>=TIMEOUT_MS;}
 bool accept(uint8_t type,uint8_t length,uint32_t now){
  if(expired(now))active=false;
  if(!active&&(type!=W_HELLO||length!=0))return false;
  active=true;lastFrame=now;return true;
 }
 bool due(uint32_t now){if(expired(now))active=false;return active&&(uint32_t)(now-lastPulse)>=PULSE_MS;}
 void pulsed(uint32_t now){lastPulse=now;}
};
#endif
